export const departmentCodes={D01:'HWI',D02:'CMP',D03:'DTE',D04:'DOP',D05:'DPL',D06:'MFG',D07:'ESC',D08:'QLT'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function departmentTag(n){return `<span class="department-tag" title="${esc(n.department_name+' · '+n.owner_team)}" aria-label="責任部門：${esc(n.department_name)}">${departmentCodes[n.department_id]||n.department_id}</span>`}
export function departmentSvgTag(n,x,y){return `<rect x="${x}" y="${y-12}" width="39" height="17" rx="8.5" fill="#e8edef" stroke="#d1dbde"/><text x="${x+19.5}" y="${y-3.5}" text-anchor="middle" dominant-baseline="central" font-family="Arial,sans-serif" font-size="9.5" fill="#526974">${departmentCodes[n.department_id]||n.department_id}</text>`}
export function watchProductDepartments(getNodes){const done=new WeakSet();let pending=false;const decorate=()=>{pending=false;const names=new Map((getNodes()||[]).map(n=>[n.product_name,n]));const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const found=[];while(walker.nextNode()){const t=walker.currentNode;if(done.has(t)||t.parentElement?.closest('script,style,svg,option,select,textarea,input,.department-tag,[data-no-dept-tag]'))continue;const n=names.get(t.textContent.trim());if(n){done.add(t);found.push([t,n])}}for(const [t,n]of found){const span=document.createElement('span');span.innerHTML=departmentTag(n);t.after(span.firstChild)}};new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(decorate)}}).observe(document.body,{childList:true,subtree:true});decorate()}

let titleMeasureContext;
export function productTitleLayout(name,measure){if(!measure){titleMeasureContext ||= document.createElement('canvas').getContext('2d');titleMeasureContext.font='600 14px Arial, sans-serif';measure=text=>titleMeasureContext.measureText(text).width}const max=208,lines=[];let rest=String(name);while(rest&&lines.length<2){let count=0;for(const char of rest){if(measure(rest.slice(0,count+char.length))>max)break;count+=char.length}if(count>=rest.length){lines.push(rest);rest='';break}if(lines.length===1){let text=rest;while(text&&measure(text+'…')>max)text=text.slice(0,-1);lines.push(text+'…');rest='';break}let split=rest.lastIndexOf(' ',count);if(split<Math.floor(count*.5))split=count;lines.push(rest.slice(0,split).trim());rest=rest.slice(split).trim()}if(!lines.length)lines.push('');return {lines,tagX:16+measure(lines.at(-1))+7,tagY:25+(lines.length-1)*16}}
